package com.ruoyi.ai.agent;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import static com.ruoyi.ai.agent.AgentJson.*;
public class B9AcceptanceMatrixMysqlTest extends TestCase {
    private A1TestFixture f;private AgentStore store;private ControlledWriteService writes;private ObjectNode source,snapshot,request;private long book;
    private void seed(int mode,boolean pretty) throws Exception {
        if(f==null)f=new A1TestFixture(true);store=new AgentStore(f.db);String sql=new String(Files.readAllBytes(Paths.get(System.getProperty("a1.module"),"sql/ai_agent_controlled_write_v2.sql")),StandardCharsets.UTF_8);f.db.execute(sql.replaceAll("(?m)^--[^\\r\\n]*","").trim());writes=new ControlledWriteService(store,f.guard,f.workbooks,f.versions,f.tx.getTransactionManager());for(String field:new String[]{"enabled","b8EffectEnabled","b9ResultEnabled","b8SheetEnabled","b9ResultSheetEnabled"})A1TestFixture.inject(writes,field,true);
        snapshot=(ObjectNode)parse("{\"id\":\"p\",\"sheetOrder\":[\"s\",\"out\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Source\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{\"0\":{\"0\":{\"v\":\"Name\"},\"1\":{\"v\":\"Amount\"}},\"1\":{\"0\":{\"v\":\"A\"},\"1\":{\"v\":7}},\"2\":{\"0\":{\"v\":\"B\"},\"1\":{\"v\":9}}}},\"out\":{\"id\":\"out\",\"name\":\"Result\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{}}}}");book=f.seed(pretty?snapshot.toPrettyString():snapshot.toString());ObjectNode ws=f.runs.workspace(book,1);
        source=obj().put("runId",UUID.randomUUID().toString()).put("userId",1L).put("workbookId",book).put("branchId",ws.path("branchId").asLong()).put("revision",hash(snapshot)).put("status","COMPLETED").put("goal","只读数据集").put("version",0).put("eventSeq",0);source.set("plan",obj().set("steps",arr().add(obj().put("tool","build_dataset").put("status","SUCCEEDED"))));
        f.db.update("insert into ai_agent_run(run_id,user_id,workbook_id,branch_id,request_id,request_hash,status,state_json,row_version,updated_at,created_at) values(?,?,?,?,?,?,'COMPLETED',?,0,now(3),now(3))",text(source,"runId"),1,book,source.path("branchId").asLong(),UUID.randomUUID().toString(),hash(source),source.toString());
        ObjectNode read=obj().put("sheetId","s").put("range","A1:B3").put("headerRow",true).put("includeHidden",true).put("includeFiltered",true).put("formulaPolicy","reject");new AgentTools(store).execute(source,"build_dataset",read,snapshot);
        ArrayNode list=writes.resultArtifacts(book,1);assertEquals(1,list.size());request=obj().put("entryPoint","ordinary-ai").put("requestId",UUID.randomUUID().toString()).put("workbookId",book).put("branchId",ws.path("branchId").asLong()).put("activeSheetId","out").put("overwrite","empty-only");for(String key:new String[]{"loadedRevision","expectedDraftVersion","expectedBranchVersion"})request.set(key,ws.path(key.equals("expectedDraftVersion")?"draftVersion":key.equals("expectedBranchVersion")?"branchVersion":key));request.set("writeScopes",arr().add(obj().put("sheetId","out").put("range","A1:B3")));request.set("resultArtifact",list.get(0).path("selection"));request.remove("resultTarget");request.put("overwrite","confirmed").put("activeSheetId","s");request.set("writeScopes",arr().add(obj().put("sheetId","s").put("range","A1:F6")));request.set("resultSheetAuthorization",obj().put("anchorSheetId","s").put("newSheetName","Report").put("rowCount",3).put("columnCount",2));
        this.mode=mode;
        if(mode%2==0){request.remove("resultSheetAuthorization");request.put("overwrite","empty-only").put("activeSheetId","out");request.set("writeScopes",arr().add(obj().put("sheetId","out").put("range","A1:B3")));request.set("resultTarget",obj().put("sheetId","out").put("range","A1:B3"));}
        args=obj().put("overwrite",mode%2==0?"empty-only":"confirmed");args.set("dataset",obj().put("resultRef",request.path("resultArtifact").path("resultRef").asText()).put("sourceRevision",request.path("resultArtifact").path("sourceRevision").asText()));
        if(mode%2==1)args.set("newSheet",request.path("resultSheetAuthorization"));else args.put("sheetId","out").put("range","A1:B3");
        if(mode<2){
            source.put("kind","PLAN_AGENT").put("status","EXECUTING").put("activeSheetId",request.path("activeSheetId").asText()).put("allowOverwrite",false).put("fencingToken",1).put("planVersion",1).put("stepIndex",1).put("persistenceStatus","NOT_SAVED");
            for(String key:new String[]{"loadedRevision","expectedDraftVersion","expectedBranchVersion","writeScopes"})source.set(key,request.path(key));if(mode%2==1)source.set("resultSheetAuthorization",request.path("resultSheetAuthorization"));
            f.db.update("update ai_agent_run set status='EXECUTING',state_json=? where run_id=?",source.toString(),text(source,"runId"));f.db.update("insert into ai_agent_lease(workbook_id,run_id,fencing_token,expires_at) values(?,?,1,?)",book,text(source,"runId"),System.currentTimeMillis()+120000);
        }
    }
    private int mode;private ObjectNode args;
    @Override protected void tearDown(){if(f!=null)f.close();}
    private ObjectNode create(){if(mode>=2)return writes.create(request,1);return f.tx.execute(tx->{f.guard.lock(book,1L);ObjectNode r=store.locked(text(source,"runId"));writes.prepareResultLocked(r,args);store.save(r);return r;});}
    private ObjectNode claim(JsonNode r){return writes.claim(text(r,"runId"),1,obj().put("transportVersion",2).put("clientId","b9-matrix").set("fencingToken",r.path("fencingToken")));}
    private ObjectNode identity(JsonNode m){ObjectNode r=obj().put("transportVersion",2);for(String k:new String[]{"callId","effectId","claimToken","argsHash","fencingToken"})r.set(k,m.path(k));return r;}
    private ObjectNode receipt(JsonNode m){ObjectNode r=identity(m).put("ok",true);if(m.has("structureReadback"))r.set("structureReadback",m.path("structureReadback").deepCopy());else{ArrayNode cells=arr();for(JsonNode c:m.path("cells")){ObjectNode v=obj().put("sheetId",text(c,"sheetId")).put("row",c.path("row").asInt()).put("column",c.path("column").asInt()).put("formula","");v.set("value",c.path("value"));cells.add(v);}r.set("cells",cells);}return r;}
    private ObjectNode save(JsonNode r,ObjectNode receipt){return writes.receipt(text(r,"runId"),1,receipt,(run,result)->{run.put("status","COMPLETED");f.db.update("update ai_agent_lease set run_id=null,expires_at=0 where workbook_id=? and run_id=?",book,text(run,"runId"));});}
    private void reject(Runnable fn){try{fn.run();fail("unsafe matrix case accepted: "+mode);}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    private void none(){assertEquals(0,f.db.queryForObject("select count(*) from ai_workbook_working_state where workbook_id=?",Integer.class,book).intValue());}
    private void sourceStale(){f.db.update("update ai_analysis_artifact set source_revision='stale' where artifact_id=?",args.path("dataset").path("resultRef").asText());}
    private ObjectNode verifyArgs(JsonNode saved){ObjectNode a=obj().put("sheetId",mode%2==0?"out":"s").put("range",mode%2==0?"A1:B3":"A1:F6").put("kind",mode%2==0?"matches_write":"matches_structure");a.set("write",saved.path("lastControlledResult"));return a;}
    private void mutateRun(JsonNode r,java.util.function.Consumer<ObjectNode> change){f.tx.execute(tx->{f.guard.lock(book,1L);ObjectNode locked=store.locked(text(r,"runId"));change.accept(locked);store.save(locked);return null;});}
    private void passed(String scenario) throws Exception {String file=System.getProperty("b9.matrix.evidence");if(file!=null){ObjectNode row=obj().put("run",System.getProperty("b9.matrix.run","")).put("scenario",scenario).put("sourceBinding",mode<2?"same-run":"selected-source").put("target",mode%2==0?"existing":"new").put("status","PASS");Files.write(Paths.get(file),(row.toString()+System.lineSeparator()).getBytes(StandardCharsets.UTF_8),StandardOpenOption.CREATE,StandardOpenOption.APPEND);}}
    public void testRawContentBindingTamperRejectsAndLegacyCanonicalRecordStillVerifies() throws Exception {for(int m:new int[]{1,3}){seed(m,false);ObjectNode r=create(),call=claim(r),saved=save(r,receipt(call));JsonNode actual=parse(String.valueOf(f.status(book).get("content")));ObjectNode bad=saved.deepCopy();((ObjectNode)bad.path("lastControlledResult").path("executedChange").path("structurePatch")).put("beforeContentHash","forged");reject(()->AgentTools.verify(actual,verifyArgs(bad)));ObjectNode legacy=saved.deepCopy();((ObjectNode)legacy.path("lastControlledResult").path("executedChange").path("structurePatch")).remove("beforeContentHash");assertTrue(AgentTools.verify(actual,verifyArgs(legacy)).path("passed").asBoolean());passed("raw-content-binding-tamper-and-legacy-canonical");}}
    public void testSavedResultSourcePreservationAndOneEffect() throws Exception {for(int m=0;m<4;m++){seed(m,false);ObjectNode r=create(),call=claim(r),saved=save(r,receipt(call));assertEquals("COMPLETED",saved.path("status").asText());JsonNode actual=parse(String.valueOf(f.status(book).get("content")));assertEquals(snapshot.path("sheets").path("s"),actual.path("sheets").path("s"));if(m%2==1)assertEquals(snapshot.path("sheets").path("out"),actual.path("sheets").path("out"));assertTrue(AgentTools.verify(actual,verifyArgs(saved)).path("passed").asBoolean());assertEquals(1,f.db.queryForObject("select count(*) from ai_agent_effect where run_id=? and status='PERSISTED'",Integer.class,text(r,"runId")).intValue());passed("saved-source-preserved-one-effect");}}
    public void testOriginalContentWhitespaceDoesNotChangeSourceSemantics() throws Exception {for(int m=0;m<4;m++){seed(m,true);ObjectNode r=create(),call=claim(r);assertFalse(call.path("loadedRevision").equals(call.path("resultSource").path("sourceRevision")));ObjectNode saved=save(r,receipt(call));assertTrue(AgentTools.verify(parse(String.valueOf(f.status(book).get("content"))),verifyArgs(saved)).path("passed").asBoolean());passed("original-content-whitespace");}}
    public void testSourceChangeBeforeClaim() throws Exception {for(int m=0;m<4;m++){seed(m,false);ObjectNode r=create();sourceStale();reject(()->claim(r));none();passed("source-change-before-claim");}}
    public void testSourceChangeAfterClaim() throws Exception {for(int m=0;m<4;m++){seed(m,false);ObjectNode r=create(),call=claim(r);sourceStale();reject(()->save(r,receipt(call)));none();passed("source-change-after-claim");}}
    public void testPermissionRevokedAfterClaim() throws Exception {for(int m=0;m<4;m++){seed(m,false);ObjectNode r=create(),call=claim(r);f.db.update("update ai_workbook_branch set status='archived' where branch_id=?",r.path("branchId").asLong());reject(()->save(r,receipt(call)));none();passed("branch-permission-revoked");}}
    public void testBranchVersionChangedAfterClaim() throws Exception {for(int m=0;m<4;m++){seed(m,false);ObjectNode r=create(),call=claim(r);f.db.update("update ai_workbook_branch set version=version+1 where branch_id=?",r.path("branchId").asLong());reject(()->save(r,receipt(call)));none();passed("branch-version-changed");}}
    public void testManualContentCannotBeOverwrittenByLateReceipt() throws Exception {for(int m=0;m<4;m++){seed(m,false);ObjectNode r=create(),call=claim(r),manual=snapshot.deepCopy();manual.put("name","manual-change");String content=manual.toString();f.db.update("update ai_workbook set content=?,content_hash=? where workbook_id=?",content,com.ruoyi.ai.util.ContentHashUtils.sha256(content),book);reject(()->save(r,receipt(call)));none();assertEquals(content,f.db.queryForObject("select content from ai_workbook where workbook_id=?",String.class,book));passed("manual-current-content-preserved");}}
    public void testGateDisabledAfterClaim() throws Exception {for(int m=0;m<4;m++){seed(m,false);ObjectNode r=create(),call=claim(r);A1TestFixture.inject(writes,"b9ResultEnabled",false);reject(()->save(r,receipt(call)));none();passed("result-gate-disabled");}}
    public void testReceiptIdentityAndPayloadForgery() throws Exception {for(int m=0;m<4;m++){seed(m,false);ObjectNode r=create(),call=claim(r);for(String field:new String[]{"callId","effectId","claimToken","argsHash","fencingToken"}){ObjectNode bad=receipt(call);if("fencingToken".equals(field))bad.put(field,99999);else bad.put(field,"forged");reject(()->save(r,bad));}ObjectNode snapshotInjection=receipt(call);snapshotInjection.set("snapshot",snapshot);reject(()->save(r,snapshotInjection));ObjectNode bad=receipt(call);if(m%2==1)((ObjectNode)bad.path("structureReadback")).put("workbookDigest","forged");else ((ObjectNode)bad.path("cells").get(0)).put("value","forged");reject(()->save(r,bad));none();passed("receipt-identity-readback-snapshot-forgery");}}
    public void testLostReceiptReturnsSavedFactWithoutSecondEffect() throws Exception {for(int m=0;m<4;m++){seed(m,false);ObjectNode r=create(),call=claim(r),body=receipt(call),saved=save(r,body);sourceStale();ObjectNode retry=save(r,body),uncertain=writes.uncertain(text(r,"runId"),1,identity(call));assertEquals(WriteManifest.digest(saved.path("lastControlledResult")),WriteManifest.digest(retry.path("lastControlledResult")));assertEquals("SAVED",uncertain.path("persistenceStatus").asText());assertEquals(1,f.db.queryForObject("select count(*) from ai_agent_effect where run_id=? and status='PERSISTED'",Integer.class,text(r,"runId")).intValue());assertEquals(0L,f.db.queryForObject("select version from ai_workbook_working_state where workbook_id=?",Long.class,book).longValue());passed("lost-receipt-duplicate-and-uncertain-saved-fact");}}
    public void testUnknownFailureCannotAcceptLateSuccessOrReplay() throws Exception {for(int m=0;m<4;m++){seed(m,false);ObjectNode r=create(),call=claim(r),bad=identity(call).put("ok",false).put("error","execution interrupted");ObjectNode paused=save(r,bad);assertEquals("PAUSED",paused.path("status").asText());reject(()->save(r,receipt(call)));reject(()->claim(r));none();passed("unknown-failure-no-late-save-no-replay");}}
    public void testCancelPreparedAndClaimedCalls() throws Exception {for(int m=0;m<4;m++){for(boolean claimed:new boolean[]{false,true}){seed(m,false);ObjectNode r=create(),call=claimed?claim(r):null;mutateRun(r,locked->{locked.put("cancelRequested",true).put("status","CANCELLING");writes.reconcileLifecycleLocked(locked);});ObjectNode stopped=store.get(text(r,"runId"));assertEquals(claimed?"CANCELLING":"CANCELLED",stopped.path("status").asText());if(claimed)reject(()->save(r,receipt(call)));reject(()->claim(r));none();}passed("cancel-prepared-and-claimed-no-save");}}
    public void testExpiredLeaseCannotSaveOrReclaim() throws Exception {for(int m=0;m<4;m++){seed(m,false);ObjectNode r=create(),call=claim(r);f.db.update("update ai_agent_lease set expires_at=0 where workbook_id=?",book);reject(()->save(r,receipt(call)));reject(()->claim(r));none();passed("expired-lease-no-save-no-reclaim");}}
}

